{"path":"assets/css/styles.css","content":":root{--accent:#9aa67b;--accent-dark:#6b7a4f;--muted:#6b6b6b;--bg:#fbfbf9;--card:#ffffff}
*{box-sizing:border-box}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;margin:0;color:#222;background:var(--bg);line-height:1.5}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(255,255,255,0.7),transparent);border-bottom:1px solid #eee}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;gap:12px;align-items:center}
.brand .name{font-weight:700}
.brand .tag{font-size:13px;color:var(--muted)}
.main-nav a{margin-left:16px;color:#333;text-decoration:none}
.main-nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:6px}
.hero{padding:48px 0;background:linear-gradient(135deg,rgba(154,166,123,0.06),transparent)}
.grid-2{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
.hero-copy h1{font-size:28px;margin:0 0 12px}
.lead{color:var(--muted);margin-bottom:18px}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;text-decoration:none}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid #ddd;color:#333}
.contact-list{list-style:none;padding:0;margin:14px 0 0;color:var(--muted)}
.contact-list li{margin-bottom:6px}
.hero-art{display:flex;justify-content:center}
.pattern-wrap{position:relative;width:320px;height:240px}
.pattern-wrap .bg-pattern{position:absolute;inset:0;width:100%;height:100%;opacity:0.12}
.bottle{position:relative;width:100%;height:100%}
.pillars{padding:36px 0}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.grid-3 article{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 1px 0 rgba(0,0,0,0.04)}
.myth-truth{background:#fff6ea;padding:26px 0;margin-top:12px}
.mt-grid{display:flex;gap:18px}
.myth,.truth{flex:1;padding:12px}
.myth h4,.truth h4{margin:0 0 8px}
.case-notes{padding:36px 0}
.proof{display:flex;gap:20px;align-items:flex-start}
.testimonials{flex:1;min-height:140px;background:var(--card);padding:18px;border-radius:10px;position:relative}
.testimonial{display:none}
.testimonial.active{display:block}
.testimonial p{margin:0 0 10px}
.credibility{width:220px}
.badges{display:flex;flex-direction:column;gap:10px}
.badge{display:flex;align-items:center;gap:12px;padding:10px;border-radius:8px;background:#fff;border:1px solid #eee;cursor:pointer}
.badge .icon{width:28px;height:28px;fill:var(--accent-dark);opacity:0.9}
.badge .label{font-size:14px;color:#333}
.badge-tip{margin-top:12px;color:var(--muted);font-size:13px;min-height:40px}
.pricing{padding:36px 0}
.price-tool{background:var(--card);padding:18px;border-radius:10px}
.toggle{display:flex;align-items:center;gap:12px;margin-bottom:12px}
.switch{position:relative;display:inline-block;width:48px;height:26px}
.switch input{opacity:0;width:0;height:0}
.slider{position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:#ccc;border-radius:26px}
.slider:before{position:absolute;content:'';height:20px;width:20px;left:3px;top:3px;background:white;border-radius:50%;transition:transform 250ms}
.switch input:checked + .slider{background:var(--accent)}
.switch input:checked + .slider:before{transform:translateX(22px)}
.plans{display:flex;gap:12px}
.plan{flex:1;padding:12px;border-radius:8px;background:#fff;border:1px solid #eee}
.price{font-size:22px;font-weight:700;margin:8px 0}
.price .num{display:inline-block;min-width:36px;text-align:right}
.faq{padding:36px 0;background:transparent}
.qa{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.final-cta{background:linear-gradient(90deg,rgba(154,166,123,0.12),transparent);padding:28px;border-radius:10px;margin:18px 0}
.site-footer{border-top:1px solid #eee;background:#fff;padding:18px 0;margin-top:18px}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.small{color:var(--muted)}
@media (max-width:900px){.grid-2{grid-template-columns:1fr}.mt-grid{flex-direction:column}.grid-3{grid-template-columns:1fr}.qa{grid-template-columns:1fr}.plans{flex-direction:column}}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Year update
  document.getElementById('year').textContent = new Date().getFullYear();

  // Testimonial rotation
  const testimonials = Array.from(document.querySelectorAll('.testimonial'));
  const badges = document.getElementById('badges');
  const badgeTip = document.getElementById('badgeTip');
  let tIndex = 0;
  function showTest(i){
    testimonials.forEach((el,idx)=>el.classList.toggle('active',idx===i));
    // highlight badge if matches data-badge
    const active = testimonials[i];
    const key = active.getAttribute('data-badge');
    Array.from(badges.querySelectorAll('.badge')).forEach(b=>b.classList.toggle('active', b.getAttribute('data-key')===key));
  }
  showTest(0);
  setInterval(()=>{
    tIndex = (tIndex+1) % testimonials.length;
    showTest(tIndex);
  },4500);

  // Badge tooltips
  badges.addEventListener('mouseover', function(e){
    const btn = e.target.closest('.badge');
    if(!btn) return;
    const tip = btn.getAttribute('data-tip');
    badgeTip.textContent = tip;
  });
  badges.addEventListener('mouseout', function(){ badgeTip.textContent = ''; });

  // Pricing comparator with animated numbers
  const toggle = document.getElementById('priceToggle');
  const nums = Array.from(document.querySelectorAll('.price .num'));

  function animatePrice(el, from, to){
    const dur = 500; // ms
    const start = performance.now();
    function step(now){
      const t = Math.min(1,(now-start)/dur);
      const val = Math.round(from + (to-from)*t);
      el.textContent = val;
      if(t<1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function updatePrices(isPackage){
    nums.forEach(n=>{
      const parent = n.closest('.price');
      const month = parseInt(parent.getAttribute('data-month'),10);
      const pack = parseInt(parent.getAttribute('data-package'),10);
      const current = parseInt(n.textContent,10) || month;
      const target = isPackage ? pack : month;
      animatePrice(n,current,target);
    });
    // update toggle label
    const label = document.querySelector('.toggle-label');
    label.textContent = isPackage ? 'Package' : 'Monthly';
  }

  toggle.addEventListener('change',function(){ updatePrices(toggle.checked); });

  // Initialize prices based on default toggle state
  updatePrices(toggle.checked);

  // Accessibility: keyboard focus states for badges
  Array.from(document.querySelectorAll('.badge')).forEach(b=>{
    b.addEventListener('focus', ()=> badgeTip.textContent = b.getAttribute('data-tip'));
    b.addEventListener('blur', ()=> badgeTip.textContent = '');
  });

})();"} 
